/**
 * Full-screen background: the chicks game from `game/` (Zig + raylib + Box2D,
 * built to `game/zig-out/` by the zig-build Vite plugin). Releasing a pointer
 * anywhere on the page drops a seed there.
 *
 * The emscripten module is imported as source, so Vite bundles it into its own
 * chunk and emits the .wasm it references as a content-hashed asset. Its types
 * (`chicks.d.mts`) are generated by emcc. Page-level side effects of the
 * engine (GLFW's key listeners, the document title) are undone inside the
 * module, in `game/src/web/pre.js`.
 */

let started = false;

export function startChicks() {
	if (started) return;
	started = true;
	if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

	const canvas = document.createElement("canvas");
	// raylib finds the canvas through `#${Module.canvas.id}`.
	canvas.id = "chicks";
	canvas.setAttribute("aria-hidden", "true");
	canvas.tabIndex = -1;
	Object.assign(canvas.style, {
		position: "fixed",
		inset: "0",
		width: "100%",
		height: "100%",
		zIndex: "-1",
		pointerEvents: "none",
		imageRendering: "pixelated",
	});
	document.body.prepend(canvas);

	void load(canvas).catch((error: unknown) => {
		console.warn("chicks background disabled:", error);
		canvas.remove();
	});
}

async function load(canvas: HTMLCanvasElement) {
	const { default: createChicks } =
		await import("../../game/zig-out/chicks.mjs");
	const game = await createChicks({ canvas, print: () => {} });

	window.addEventListener(
		"pointerup",
		(e) => game._chicks_click(e.clientX, e.clientY, e.button),
		{ capture: true, passive: true },
	);
}
